function Get-AI5GeminiApiCredentialStatus {Get-AI5ApiNodeStatus 'gemini_api'}
function New-AI5GeminiApiRequest {param($Task,[string]$Model='gemini');if(!$Task.TASK_ID-or!$Task.CORRELATION_ID){throw 'zero_task_identity_required'};[ordered]@{provider='google';node='gemini_api';model=$Model;task_id=$Task.TASK_ID;correlation_id=$Task.CORRELATION_ID;purpose=$Task.PURPOSE;canonical_repo=$Task.CANONICAL_REPO;canonical_branch=$Task.CANONICAL_BRANCH;allowed_actions=@($Task.ALLOWED_ACTIONS);prohibited_actions=@($Task.PROHIBITED_ACTIONS);expected_result=$Task.EXPECTED_RESULT}}
function Invoke-AI5GeminiApiAdapter {param($Task);$health=Get-AI5GeminiApiCredentialStatus;if($health.status-ne'NOT_WIRED'){return [ordered]@{TASK_ID=$Task.TASK_ID;CORRELATION_ID=$Task.CORRELATION_ID;AGENT='gemini_api';STATUS=$health.status;SUMMARY='Gemini API credential is not configured';EVIDENCE=@();ATTEMPT=1;FINISHED_AT=[DateTime]::UtcNow.ToString('o')}};[ordered]@{TASK_ID=$Task.TASK_ID;CORRELATION_ID=$Task.CORRELATION_ID;AGENT='gemini_api';STATUS='NOT_WIRED';SUMMARY='Credential exists but live transport is not yet verified';EVIDENCE=@();ATTEMPT=1;FINISHED_AT=[DateTime]::UtcNow.ToString('o')}}
